150	/// The wizard's questions; a scripted implementation drives tests. Esc or Ctrl-C at any of them is
151	/// [`CliError::Cancelled`].
152	trait AddPrompter {
153	    /// The indices the contributor ticked; `checked` says which start ticked.
154	    fn multi_select(&mut self, prompt: &str, items: &[String], checked: &[bool]) -> Result<Vec<usize>, CliError>;
155	    /// The summary; an empty answer opens `$EDITOR` for a longer one. `None` when the editor saves nothing.
156	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError>;
157	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
158	}
159	
160	/// Rows a package list shows before it pages.
161	const PAGE: usize = 15;
162	
163	struct TerminalAddPrompter {
164	    _allowed: tty::Prompts,
165	}
166	
167	impl AddPrompter for TerminalAddPrompter {
168	    fn multi_select(&mut self, prompt: &str, items: &[String], checked: &[bool]) -> Result<Vec<usize>, CliError> {
169	        let ticked: Vec<usize> = checked
170	            .iter()
171	            .enumerate()
172	            .filter(|(_, on)| **on)
173	            .map(|(index, _)| index)
174	            .collect();
175	        let picked = tty::prompt(|| {
176	            MultiSelect::new(prompt, items.to_vec())
177	                .with_default(&ticked)
178	                .with_page_size(tty::page_size(PAGE))
179	                .raw_prompt()
180	        })?;
181	        Ok(picked.into_iter().map(|option| option.index).collect())
182	    }
183	
184	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError> {
185	        let mut editor = tty::Editor::from_env();
186	        loop {
187	            let hint = match &editor {
188	                Some(editor) => format!("{prompt} (leave empty to open ${}; Esc cancels)", editor.variable()),
189	                None => format!("{prompt} (Esc cancels)"),
190	            };
191	            let opens_editor = editor.is_some();
192	            let line = tty::prompt(|| {
193	                Text::new(&hint)
194	                    .with_validator(move |line: &str| {
195	                        Ok(match Summary::new(line) {
196	                            Err(error) if !(opens_editor && line.is_empty()) => {
197	                                Validation::Invalid(error.to_string().into())
198	                            }
199	                            _ => Validation::Valid,
200	                        })
201	                    })
202	                    .prompt()
203	            })?;
204	            if let Ok(summary) = Summary::new(&line) {
205	                return Ok(Some(summary));
206	            }
207	            // The validator lets an empty line through only when there is an editor to open.
208	            let Some(chosen) = editor.take() else { continue };
209	            match chosen.edit() {
210	                Ok(saved) => return Ok(saved.and_then(|text| Summary::new(&text).ok())),
211	                // The answers so far are kept: the summary is asked for inline instead.
212	                Err(unusable) => prompt_line(&format!("warning: {unusable}")),
213	            }
214	        }
215	    }
216	
217	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
218	        tty::prompt(|| Confirm::new(prompt).with_default(default).prompt())
219	    }
220	}
