222	/// A package the wizard offers, and whether it changed since its last tag.
223	struct Choice {
224	    name: String,
225	    changed: bool,
226	}
227	
228	/// The interactive wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor (the
229	/// remainder default to patch), a summary unless one was given, then a review to confirm. Changed packages are listed
230	/// first and start ticked. `None` when the contributor declines the review or the editor saves nothing, having been
231	/// told nothing was written.
232	fn run_wizard(
233	    choices: &[Choice],
234	    summary: Option<Summary>,
235	    prompter: &mut impl AddPrompter,
236	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
237	    let answers = ask(choices, summary, prompter)?;
238	    if answers.is_none() {
239	        prompt_line(tty::CANCELLED);
240	    }
241	    Ok(answers)
242	}
243	
244	fn ask(
245	    choices: &[Choice],
246	    summary: Option<Summary>,
247	    prompter: &mut impl AddPrompter,
248	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
249	    if choices.is_empty() {
250	        return Err(CliError::AddNoPackagesInWorkspace);
251	    }
252	
253	    let mut ordered: Vec<&Choice> = choices.iter().collect();
254	    ordered.sort_by_key(|choice| !choice.changed);
255	    let labels: Vec<String> = ordered
256	        .iter()
257	        .map(|choice| {
258	            if choice.changed {
259	                format!("{} (changed)", choice.name)
260	            } else {
261	                choice.name.clone()
262	            }
263	        })
264	        .collect();
265	    let checked: Vec<bool> = ordered.iter().map(|choice| choice.changed).collect();
266	    let selected_indices = prompter.multi_select(
267	        "Packages in this change (Space toggles, Enter confirms, Esc cancels)",
268	        &labels,
269	        &checked,
270	    )?;
271	    if selected_indices.is_empty() {
272	        return Err(CliError::AddNoPackagesSelected);
273	    }
274	    let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| ordered[i].name.clone()).collect();
275	    let unticked = vec![false; selected_packages.len()];
276	
277	    let majors = prompter.multi_select(
278	        "Which are a MAJOR bump? (breaking changes only)",
279	        &selected_packages,
280	        &unticked,
281	    )?;
282	    let major_set: std::collections::HashSet<usize> = majors.into_iter().collect();
283	
284	    let minor_candidates: Vec<String> = selected_packages
285	        .iter()
286	        .enumerate()
287	        .filter(|(idx, _)| !major_set.contains(idx))
288	        .map(|(_, name)| name.clone())
289	        .collect();
290	    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
291	        std::collections::HashSet::new()
292	    } else {
293	        let minors = prompter.multi_select(
294	            "Which are a MINOR bump? (the rest get PATCH)",
295	            &minor_candidates,
296	            &unticked[..minor_candidates.len()],
297	        )?;
298	        minors.into_iter().map(|idx| minor_candidates[idx].clone()).collect()
299	    };
300	
301	    let entries: Vec<Entry> = selected_packages
302	        .iter()
303	        .enumerate()
304	        .map(|(idx, name)| Entry {
305	            name: name.clone(),
306	            severity: if major_set.contains(&idx) {
307	                Severity::Major
308	            } else if minor_set.contains(name) {
309	                Severity::Minor
310	            } else {
311	                Severity::Patch
312	            },
313	        })
314	        .collect();
315	
316	    let summary = match summary {
317	        Some(summary) => summary,
318	        None => match prompter.summary("Changelog summary")? {
319	            Some(summary) => summary,
320	            None => return Ok(None),
321	        },
322	    };
323	
324	    prompt_line(&review(&entries, &summary.0));
325	    Ok(prompter
326	        .confirm("Write this changeset?", true)?
327	        .then_some((entries, summary)))
328	}
329	
330	/// What the changeset will record: each package's bump, then the summary as it reaches the changelog.
331	fn review(entries: &[Entry], summary: &str) -> String {
332	    let mut text = String::from("\nThis changeset records:\n");
333	    for entry in entries {
334	        text.push_str(&format!("  {:<5}  {}\n", entry.severity.to_string(), entry.name));
335	    }
336	    text.push('\n');
337	    for line in summary.trim().lines() {
338	        text.push_str(&format!("  {line}\n"));
339	    }
340	    text
341	}
