343	/// Parses a CLI-supplied severity string, reporting every value `Severity`
344	/// actually accepts (`none`, `patch`, `minor`, `major`) on failure -- not a
345	/// stale subset that omits `none`.
346	fn parse_severity(sev_str: &str) -> Result<Severity, CliError> {
347	    sev_str.parse().map_err(|_err| CliError::InvalidSeverity {
348	        value: sev_str.to_string(),
349	    })
350	}
