352	/// The wizard's packages, named by `.display_name()` so `cargo/foo` and `npm/foo` stay distinct in a polyglot workspace.
353	/// When the changed packages cannot be worked out, says so once and offers every package unticked.
354	fn wizard_choices<'a>(
355	    packages: impl Iterator<Item = &'a callisto_model::Package>,
356	    changed: Result<std::collections::BTreeMap<callisto_model::PackageId, bool>, callisto_graph::GraphError>,
357	) -> Vec<Choice> {
358	    let changed = changed.unwrap_or_else(|error| {
359	        prompt_line(&format!(
360	            "warning: could not tell which packages changed since their last release, so none is ticked: {error}"
361	        ));
362	        std::collections::BTreeMap::new()
363	    });
364	    packages
365	        .map(|pkg| Choice {
366	            name: pkg.id.display_name(),
367	            changed: changed.get(&pkg.id).copied().unwrap_or(false),
368	        })
369	        .collect()
370	}
