372	/// Writes `text` to a new file in `dir` named by `next_slug`, trying another slug whenever the name is taken, including
373	/// by a changeset another process created after this one looked. Nothing already in `dir` is ever replaced.
374	fn create_changeset(
375	    dir: &std::path::Path,
376	    archive: &std::path::Path,
377	    text: &str,
378	    permit: &ApplyPermit,
379	    mut next_slug: impl FnMut() -> String,
380	) -> Result<String, CliError> {
381	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
382	    for _ in 0..64 {
383	        let filename = format!("{}.md", next_slug());
384	        if archived(archive, &filename)? {
385	            continue;
386	        }
387	        let path = dir.join(&filename);
388	        match callisto_model::atomic::atomic_write_new(&path, text, permit) {
389	            Ok(()) => return Ok(filename),
390	            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
391	            Err(source) => {
392	                return Err(CliError::Io {
393	                    source,
394	                    path: Some(path),
395	                })
396	            }
397	        }
398	    }
399	    Err(CliError::Io {
400	        source: std::io::Error::new(
401	            std::io::ErrorKind::AlreadyExists,
402	            "no unused changeset filename found after 64 attempts",
403	        ),
404	        path: Some(dir.to_path_buf()),
405	    })
406	}
407	
408	/// Whether a Changesets v3 pre cycle archived a note under `filename`; a new note there would read as its duplicate.
409	fn archived(archive: &std::path::Path, filename: &str) -> Result<bool, CliError> {
410	    let path = archive.join(filename);
411	    callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
412	        source,
413	        path: Some(path),
414	    })
415	}
416	
417	/// Picks a changeset filename that does not exist yet, so a slug collision never overwrites a pending changeset.
418	fn unused_changeset_filename(dir: &std::path::Path, archive: &std::path::Path) -> Result<String, CliError> {
419	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
420	    for _ in 0..64 {
421	        let filename = format!("{}.md", generate_human_slug());
422	        let path = dir.join(&filename);
423	        let taken = callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
424	            source,
425	            path: Some(path.clone()),
426	        })?;
427	        if !taken && !archived(archive, &filename)? {
428	            return Ok(filename);
429	        }
430	    }
431	    Err(CliError::Io {
432	        source: std::io::Error::new(
433	            std::io::ErrorKind::AlreadyExists,
434	            "no unused changeset filename found after 64 attempts",
435	        ),
436	        path: Some(dir.to_path_buf()),
437	    })
438	}
439	
440	fn generate_human_slug() -> String {
441	    use std::sync::atomic::{AtomicU64, Ordering};
442	
443	    static COUNTER: AtomicU64 = AtomicU64::new(0);
444	
445	    let adjectives = [
446	        "swift", "clever", "bright", "silent", "brave", "calm", "eager", "gentle", "happy", "jolly", "keen", "lively",
447	        "mighty", "noble", "proud", "quick", "radiant", "sharp", "tough", "vivid",
448	    ];
449	    let nouns = [
450	        "foxes", "hawks", "wolves", "eagles", "bears", "lions", "otters", "pandas", "falcons", "tigers", "dolphins",
451	        "panthers", "cheetahs", "leopards", "ravens", "badgers", "lynxes", "cobras", "owls", "stags",
452	    ];
453	    let verbs = [
454	        "run", "fly", "leap", "soar", "dash", "hunt", "glide", "climb", "swim", "roar", "pounce", "sprint", "chase",
455	        "race", "bound", "drift", "jump", "strut", "spin", "surge",
456	    ];
457	
458	    // Each word list has 20 entries; consecutive counter values map to unique triples (a = idx % 20, n = (idx / 20) % 20,
459	    // v = (idx / 400) % 20), a bijection on 0..7999. A timestamp-derived offset varies the start across process restarts.
460	    let ts = std::time::SystemTime::now()
461	        .duration_since(std::time::UNIX_EPOCH)
462	        .map(|d| d.as_nanos() as u64)
463	        .unwrap_or(0);
464	
465	    let count = COUNTER.fetch_add(1, Ordering::Relaxed);
466	    // Shift ts right to get a slowly-varying cross-run offset (changes every ~1 µs).
467	    let offset = (ts >> 10) % 8000;
468	    let idx = (count + offset) % 8000;
469	
470	    let a = adjectives[(idx % 20) as usize];
471	    let n = nouns[((idx / 20) % 20) as usize];
472	    let v = verbs[((idx / 400) % 20) as usize];
473	
474	    format!("{a}-{n}-{v}")
475	}
