74	impl Prompter for TerminalPrompter {
75	    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError> {
76	        Ok(tty::prompt(|| {
77	            Select::new(prompt, items.to_vec())
78	                .with_page_size(tty::page_size(PAGE))
79	                .raw_prompt()
80	        })?
81	        .index)
82	    }
83	
84	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
85	        tty::prompt(|| Confirm::new(prompt).with_default(default).prompt())
86	    }
87	
88	    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError> {
89	        let mut input = Text::new(prompt);
90	        if let Some(default) = default {
91	            input = input.with_default(default);
92	        }
93	        tty::prompt(|| input.prompt())
94	    }
95	}
