109	/// `init` against explicit terminal state, prompter, output streams, and command runner.
110	pub fn run<R: CommandRunner>(
111	    args: InitArgs,
112	    global: &GlobalArgs,
113	    interactive: bool,
114	    prompter: &mut dyn Prompter,
115	    out: &mut dyn Write,
116	    err: &mut dyn Write,
117	    runner: &R,
118	) -> Result<ExitCode, CliError> {
119	    validate_flags(&args)?;
120	    // A repository whose manifests all sit in subdirectories has no root yet: init makes the Git toplevel one.
121	    let (root, no_root) = match workspace_root(global, runner) {
122	        Ok(root) => (root, None),
123	        Err(CliError::Locate(LocateError::WorkspaceRootNotFound { start, toplevel })) => (
124	            toplevel.clone(),
125	            Some(LocateError::WorkspaceRootNotFound { start, toplevel }),
126	        ),
127	        Err(error) => return Err(error),
128	    };
129	    let locator = IgnoreWalkLocator::new(&root);
130	    if args.workflow && scaffold::is_initialized(&root)? {
131	        // Answers feed callisto.toml, which stays as it is: refuse them rather than drop them.
132	        // The forge and product flags already require an artifact target.
133	        if args.versioning.is_some() || !args.artifact_targets.is_empty() {
134	            return Err(GraphError::InitAlreadyInitialized {
135	                path: root.join("callisto.toml"),
136	            }
137	            .into());
138	        }
139	        return run_workflow_only(&root, &locator, global, out, err, runner);
140	    }
141	    let facts = scaffold::detect(&root, &locator, runner)?;
142	    if let Some(error) = no_root.filter(|_| facts.packages.is_empty()) {
143	        return Err(error.into());
144	    }
145	    let json = global.format == OutputFormat::Json;
146	    // JSON keeps stdout for the report.
147	    let human: &mut dyn Write = if json { &mut *err } else { &mut *out };
148	    write_facts(&facts, human)?;
149	
150	    if facts.origin.is_none() {
151	        if args.workflow {
152	            return Err(CliError::InitFlagRequiresOrigin { flag: "workflow" });
153	        }
154	        if !args.artifact_targets.is_empty() {
155	            return Err(CliError::InitFlagRequiresOrigin {
156	                flag: "artifact-target",
157	            });
158	        }
159	    }
160	    if !interactive && !args.yes {
161	        let mut missing = vec!["--yes"];
162	        missing.extend(missing_flags(&args, &facts));
163	        return Err(CliError::InitRequiresYes { missing });
164	    }
165	    if args.yes {
166	        let missing = missing_flags(&args, &facts);
167	        if !missing.is_empty() {
168	            return Err(CliError::InitMissingFlags { missing });
169	        }
170	    }
171	    let prompting = interactive && !args.yes;
172	    let migration = changesets::migrate(&facts.root, &facts);
173	    // A dry run writes nothing, so it previews with the warning instead.
174	    if !migration.public_scoped.is_empty() && !args.yes && !global.dry_run {
175	        return Err(CliError::InitChangesetsAccess {
176	            packages: migration.public_scoped,
177	        });
178	    }
179	    let mut answers = collect_answers(&args, &facts, prompting, prompter)?;
180	
181	    let mut diagnostics = migration.diagnostics.clone();
182	    diagnostics.extend(migration.apply_fixed_groups(&mut answers));
183	    if facts.origin.is_none() {
184	        writeln!(human, "{ORIGIN_MISSING_NOTE}")?;
185	        diagnostics.push(callisto_model::Diagnostic {
186	            code: callisto_model::DiagnosticCode::InitOriginMissing,
187	            severity: callisto_model::DiagnosticSeverity::Warning,
188	            message: ORIGIN_MISSING_NOTE.to_owned(),
189	            package: None,
190	            path: None,
191	            escalated_by: None,
192	            governed_by: None,
193	        });
194	    }
195	    let shape = match scaffold::workflow_shape(&facts, answers.binaries.is_some()) {
196	        Err(reason) if args.workflow => {
197	            return Err(GraphError::InitWorkflowUnsupported {
198	                reason: reason.to_string(),
199	            }
200	            .into());
201	        }
202	        Err(reason) => {
203	            let note = workflow_unsupported_note(reason);
204	            writeln!(human, "{note}")?;
205	            diagnostics.push(callisto_model::Diagnostic {
206	                code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
207	                severity: callisto_model::DiagnosticSeverity::Warning,
208	                message: note,
209	                package: None,
210	                path: None,
211	                escalated_by: None,
212	                governed_by: None,
213	            });
214	            None
215	        }
216	        Ok(shape) => Some(shape),
217	    };
218	    let want_workflow = match shape {
219	        None => false,
220	        Some(_) if args.workflow => true,
221	        Some(_) if args.no_workflow => false,
222	        Some(_) if prompting && facts.origin.is_some() => prompter.confirm(WORKFLOW_PROMPT, true)?,
223	        // The workflow is GitHub Actions, so only a GitHub origin gets it unasked.
224	        Some(_) => facts.origin_repository.is_some(),
225	    };
226	    // A workflow nobody asked for (the default) never fails `init`: if it cannot be built, say why and go on.
227	    let asked_for_workflow = args.workflow || prompting;
228	    let workflow = match shape.filter(|_| want_workflow) {
229	        Some(shape) => match build_workflow(&facts, shape, migration.base_branch.as_ref(), runner, human) {
230	            Ok(built) => Some(built),
231	            Err(error) if !asked_for_workflow => {
232	                let note =
233	                    format!("Skipping the GitHub Actions workflow: {error}. Run `callisto init --workflow` to retry.");
234	                writeln!(human, "{note}")?;
235	                diagnostics.push(callisto_model::Diagnostic {
236	                    code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
237	                    severity: callisto_model::DiagnosticSeverity::Warning,
238	                    message: note,
239	                    package: None,
240	                    path: None,
241	                    escalated_by: None,
242	                    governed_by: None,
243	                });
244	                None
245	            }
246	            Err(error) => return Err(error),
247	        },
248	        None => None,
249	    };
250	    if workflow.is_none() {
251	        diagnostics.extend(migration.base_branch_unused());
252	    }
253	
254	    let config = scaffold::render_config(&facts, &answers);
255	    let plan = if facts.has_commit {
256	        Some(scaffold::preview(&facts, &config, &locator, runner)?)
257	    } else {
258	        None
259	    };
260	    if config
261	        .lines()
262	        .all(|line| line.trim().is_empty() || line.trim_start().starts_with('#'))
263	    {
264	        writeln!(human, "\ncallisto.toml: no settings needed, the defaults apply.")?;
265	    } else {
266	        writeln!(human, "\ncallisto.toml:\n{config}")?;
267	    }
268	    match plan {
269	        Some(plan) => {
270	            writeln!(human, "First release preview (`callisto release --dry-run`):")?;
271	            super::release::write_release_preview(plan.as_ref(), OutputFormat::Text, human)?;
272	        }
273	        None => writeln!(human, "{NO_COMMITS}")?,
274	    }
275	    if let Some((workflow, _)) = &workflow {
276	        writeln!(
277	            human,
278	            "\n{}:\n{workflow}",
279	            scaffold::workflow_path(&facts.root).display()
280	        )?;
281	    }
282	
