435	fn write_facts(facts: &InitFacts, out: &mut dyn Write) -> Result<(), CliError> {
436	    let ecosystems: Vec<&str> = facts.ecosystems.iter().map(|ecosystem| ecosystem.prefix()).collect();
437	    writeln!(out, "Detected:")?;
438	    writeln!(out, "  ecosystems: {}", ecosystems.join(", "))?;
439	    writeln!(out, "  origin: {}", facts.origin.as_deref().unwrap_or("none"))?;
440	    writeln!(out, "  packages:")?;
441	    for package in &facts.packages {
442	        let tag = package.last_tag.as_ref().map_or("none", |tag| tag.as_str());
443	        write!(out, "    {} {} (last tag: {tag}", package.id, package.version)?;
444	        if package.is_binary() {
445	            write!(out, "; binary: {}", package.bin_names.join(", "))?;
446	        }
447	        writeln!(out, ")")?;
448	    }
449	    Ok(())
