469	fn collect_answers(
470	    args: &InitArgs,
471	    facts: &InitFacts,
472	    prompting: bool,
473	    prompter: &mut dyn Prompter,
474	) -> Result<InitAnswers, CliError> {
475	    let versioning = match args.versioning {
476	        Some(InitVersioning::Fixed) => Versioning::Fixed,
477	        Some(InitVersioning::Independent) => Versioning::Independent,
478	        // Fixed and independent mean the same for one package, so only several packages are asked.
479	        None if prompting && facts.packages.len() > 1 => {
480	            let choices: Vec<String> = VERSIONING_CHOICES.iter().map(|choice| (*choice).to_owned()).collect();
481	            match prompter.select(VERSIONING_PROMPT, &choices)? {
482	                0 => Versioning::Independent,
483	                _ => Versioning::Fixed,
484	            }
485	        }
486	        None => Versioning::Independent,
487	    };
488	    let no_binaries = InitAnswers {
489	        versioning,
490	        binaries: None,
491	        fixed_groups: Vec::new(),
492	    };
493	
494	    let binaries: Vec<&InitPackage> = facts.binary_packages().collect();
495	    if binaries.is_empty() && !args.artifact_targets.is_empty() {
496	        if let Some(package) = facts.unsupported_artifact_packages().next() {
497	            return Err(GraphError::InitUnsupportedArtifactBuilder {
498	                package: package.id.clone(),
499	                ecosystem: package
500	                    .id
501	                    .split_once('/')
502	                    .map_or("unknown", |(ecosystem, _)| ecosystem)
503	                    .to_owned(),
504	            }
505	            .into());
506	        }
507	        return Err(GraphError::InitNoBinaryPackage.into());
508	    }
509	    let requested_product = args
510	        .product_package
511	        .as_deref()
512	        .map(|name| facts.product_package(name))
513	        .transpose()?;
514	    if binaries.is_empty() {
515	        return Ok(no_binaries);
516	    }
517	    // No `origin`: the forge question below has nothing to validate a repository against, so
518	    // shipping is never offered (skips straight to `no_binaries`); `--artifact-target` without
519	    // `origin` is already rejected up front in `run`.
520	    let ship = !args.artifact_targets.is_empty()
521	        || (facts.origin.is_some() && prompting && prompter.confirm(SHIP_PROMPT, false)?);
522	    if !ship {
523	        return Ok(no_binaries);
524	    }
525	    // A release goes to origin's GitHub repository, so shipping needs one.
526	    if facts.origin_repository.is_none() {
527	        return Err(GraphError::ReleaseForgeRepositoryMissing.into());
528	    }
529	
530	    let product = match (requested_product, binaries.as_slice()) {
531	        (Some(product), _) => product,
532	        (None, [only]) => only,
533	        (None, _) if prompting => {
534	            let ids: Vec<String> = binaries.iter().map(|package| package.id.clone()).collect();
535	            binaries[prompter.select(PRODUCT_PROMPT, &ids)?]
536	        }
537	        (None, _) => return Err(missing("--product-package")),
538	    };
539	
540	    let targets = if args.artifact_targets.is_empty() {
541	        loop {
542	            let answer = prompter.input(TARGETS_PROMPT, None)?;
543	            let targets: Vec<String> = answer.split(',').map(str::trim).map(str::to_owned).collect();
544	            if targets.iter().all(|target| target.is_empty()) {
545	                // Nothing meaningful submitted: re-ask rather than error.
546	                continue;
547	            }
548	            break targets;
549	        }
550	    } else {
551	        args.artifact_targets.clone()
552	    };
553	    let targets = scaffold::validate_targets(&targets)?;
554	
555	    Ok(InitAnswers {
556	        versioning,
557	        binaries: Some(BinaryRelease {
558	            product: product.id.clone(),
559	            targets,
560	        }),
561	        fixed_groups: Vec::new(),
562	    })
563	}
